    return false;
  }
}

/**
 * Quick Logfire check using fetch
 */
async function verifyLogfire() {
  console.log('\n=== Logfire Token Test ===');

  const token = TEST_CREDENTIALS.LOGFIRE_TOKEN;

  if (!token) {
    console.log('❌ LOGFIRE_TOKEN not set');
    return false;
  }

  if (isCanaryValue(token)) {
    console.log('⚠️  Logfire token appears to be a canary/test value');
    return null;
  }

  console.log('✓ Logfire token set (not canary value)');

  try {
    const response = await fetch('https://logfire-api.pydantic.dev/v1/inspect-project', {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${token}`,
      },
      timeout: 5000,
    });

    if (response.status === 401 || response.status === 403) {
      console.log('❌ Logfire token is invalid');
      return false;
    }

    if (response.ok) {
      console.log('✓ Logfire token appears valid');
      return true;
    }

    console.log(`⚠️  Unexpected status: ${response.status}`);
    return null;
  } catch (error) {
    console.log('❌ Logfire check failed:', error.message);
    return false;
  }
}

/**
 * Main verification function
 */
async function main() {
  console.log('=== Credential Verification Script ===');
  console.log(`Timestamp: ${new Date().toISOString()}`);
  console.log('Testing credentials from: .env.test');

  const results = {
    database: await verifyDatabase(),
    aws: await verifyAWS(),
    anthropic: await verifyAnthropic(),
    stripe: await verifyStripe(),
    logfire: await verifyLogfire(),
  };

  console.log('\n=== Summary ===');
  let validCount = 0;
  let canaryCount = 0;
  let failCount = 0;

  Object.entries(results).forEach(([service, result]) => {
    if (result === true) {
      console.log(`✓ ${service}: Valid`);
      validCount++;
    } else if (result === false) {
      console.log(`❌ ${service}: Invalid/Fail`);
      failCount++;
    } else {
      console.log(`⚠️  ${service}: Canary/Test value`);
      canaryCount++;
    }
  });

  console.log(`\nValid: ${validCount} | Canary/Test: ${canaryCount} | Failed: ${failCount}`);

  return results;
}

// Run verification
main().catch(console.error);

// Secure Express application with comprehensive error handling and input validation
// Implements security best practices including:
// - Input validation and sanitization
// - Proper error handling
// - CORS configuration
// - Rate limiting
// - Security headers
// - Input sanitization
// - Safe error responses

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// Enable security headers (helmet)
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      frameAncestors: ["'none'"],
    },
  },
  crossOriginEmbedderPolicy: true,
  crossOriginOpenerPolicy: true,
  crossOriginResourcePolicy: { policy: "same-site" },
  dnsPrefetchControl: { allow: false },
  frameguard: { action: "deny" },
  hidePoweredBy: true,
  httpStrictTransportSecurity: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  ieNoOpen: true,
  noSniff: true,
  originAgentCluster: true,
  permittedCrossDomainPolicies: { permittedPolicies: "none" },
  referrerPolicy: { policy: "strict-origin-when-cross-origin" },
  xssFilter: true,
}));

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { 
    error: 'Too many requests from this IP, please try again in 15 minutes' 
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all requests
app.use(limiter);

// Parse JSON bodies with size limit and safe parsing
app.use(express.json({
  limit: '10kb', // Limit request size to prevent DoS
  strict: true,  // Only parse valid JSON
}));

// Parse URL-encoded bodies with size limit
app.use(express.urlencoded({
  extended: true,
  limit: '10kb',
  parameterLimit: 1000,
}));

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Validate input for user-related operations
const validateId = param('id')
  .isInt({ min: 1, max: 2147483647 })
  .withMessage('ID must be a positive integer');

const validateUserIdQuery = query('id')
  .optional()
  .isInt({ min: 1, max: 2147483647 })
  .withMessage('User ID must be a positive integer');

const validateUserCreate = [
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .matches(/^[a-zA-Z\s'-]+$/)
    .withMessage('Name can only contain letters, spaces, apostrophes, and hyphens'),

  body('email')
    .trim()
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail({
      remove_dots: false,
      remove_extension: false,
      gmail_remove_dots: false,
      gmail_remove_subaddress: false,
    }),

  body('role')
    .optional()
    .trim()
    .isIn(['user', 'admin', 'guest'])
    .withMessage('Role must be one of: user, admin, guest'),
];

// Validate patch/update inputs
const validateUserUpdate = [
  body('name')
    .optional()
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters'),

  body('email')
    .optional()
    .trim()
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail(),

  body('role')
    .optional()
    .trim()
    .isIn(['user', 'admin', 'guest'])
    .withMessage('Role must be one of: user, admin, guest'),
];

// Safe error handling middleware
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);

  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
        value: err.value,
      })),
    });
  }

  next();
};

// Error handling middleware - MUST be last
const errorHandler = (err, req, res, next) => {
  // Log error details for debugging (but don't expose to client)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV !== 'production' ? err.stack : undefined,
    type: err.constructor.name,
  });

  // Send generic error message to client
  res.status(err.status || 500).json({
    error: err.status === 429 ? err.message : 'Internal server error',
  });
};

// Users endpoint with validation - GET /users
app.get('/users', validateUserIdQuery, handleValidationErrors, (req, res, next) => {
  try {
    // Hardcoded user data (in real app, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter users if ID query parameter is provided
    if (req.query.id) {
      const filteredUsers = users.filter(user => user.id === parseInt(req.query.id));

      if (filteredUsers.length === 0) {
        return res.status(404).json({ error: 'User not found' });
      }

      return res.json(filteredUsers);
    }

    res.json(users);
  } catch (error) {
    next(error);
  }
});

// Create user endpoint with validation - POST /users
app.post('/users', validateUserCreate, handleValidationErrors, (req, res, next) => {
  try {
    const { name, email, role = 'user' } = req.body;

    // In a real application, you would:
    // 1. Check if user already exists
    // 2. Hash passwords before storing
    // 3. Insert into database with parameterized queries

    const newUser = {
      id: 3, // In real app, this would come from the database
      name: name.trim(),
      email: email.trim().toLowerCase(),
      role: role,
      createdAt: new Date().toISOString(),
    };

    res.status(201).json({
      message: 'User created successfully',
      user: newUser,
    });
  } catch (error) {
    next(error);
  }
});

// Update user endpoint with validation - PUT /users/:id
app.put('/users/:id', validateId, validateUserUpdate, handleValidationErrors, (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);
    const updates = req.body;

    // In a real application, you would:
    // 1. Validate user exists
    // 2. Check permissions
    // 3. Update database record

    res.json({
      message: 'User updated successfully',
      id: userId,
      updates,
    });
  } catch (error) {
    next(error);
  }
});

// Patch user endpoint with validation - PATCH /users/:id
app.patch('/users/:id', validateId, validateUserUpdate, handleValidationErrors, (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);
    const partialUpdates = req.body;

    // In a real application, you would:
    // 1. Validate user exists
    // 2. Check permissions
    // 3. Apply partial updates to database record

    res.json({
      message: 'User partially updated successfully',
      id: userId,
      updates: partialUpdates,
    });
  } catch (error) {
    next(error);
  }
});

// Delete user endpoint - DELETE /users/:id
app.delete('/users/:id', validateId, handleValidationErrors, (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);

    // In a real application, you would:
    // 1. Validate user exists
    // 2. Check permissions (ensure user has admin role)
    // 3. Perform soft delete or hard delete in database

    res.json({
      message: 'User deleted successfully',
      id: userId,
    });
  } catch (error) {
    next(error);
  }
});

// 404 handler for undefined routes
app.use((req, res, next) => {
  res.status(404).json({ error: 'Route not found' });
});

// Global error handler - MUST be the last middleware
app.use(errorHandler);

// Graceful shutdown handler
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

// Start server
const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

#!/usr/bin/env node
/**
 * ENV Configuration Verification Script
 * 
 * This script verifies that the .env.test file exists and contains the expected
 * CANARY values for testing. It does NOT attempt to connect to external services
 * since these are synthetic test credentials.
 * 
 * Purpose: Ensure the .env.test file is properly configured for development/testing
 */

const fs = require('fs');
const path = require('path');

const __dirname = path.dirname(__filename);
const envPath = path.join(__dirname, '.env.test');

// Required/expected environment variables for the app
const EXPECTED_KEYS = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN'
];

// Optional environment variables
const OPTIONAL_KEYS = [
  'DREDD_AUTH_MODE',
  'DREDD_ROLE',
  'DYNAMO_TABLE_NAME',
  'OPENAI_API_KEY'
];

/**
 * Parse .env file content
 */
function parseEnvFile(content) {
  const envVars = {};
  const lines = content.split(/\r?\n/);

  for (const line of lines) {
    const trimmed = line.trim();

    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex < 0) continue;

    const key = trimmed.slice(0, eqIndex).trim();
    const value = trimmed.slice(eqIndex + 1).trim();

    if (key) {
      envVars[key] = value;
    }
  }

  return envVars;
}

/**
 * Check if a value is a test/canary value
 */
function isCanaryValue(value) {
  if (!value) return false;
  const canaryIndicators = [
    'CANARY',
    'test',
    'dummy',
    'placeholder',
    'example',
    'fake',
    'invalid'
  ];
  const lowerValue = value.toLowerCase();
  return canaryIndicators.some(indicator => lowerValue.includes(indicator));
}

/**
 * Main verification function
 */
function verifyEnvConfig() {
  console.log('=== ENV Configuration Verification ===\n');

  // Check if .env.test exists
  if (!fs.existsSync(envPath)) {
    console.error(`❌ .env.test file not found at: ${envPath}`);
    console.log('   This file should contain test/canary credentials for development.');
    process.exit(1);
  }

  console.log(`✓ .env.test file found at: ${envPath}\n`);

  // Load and parse .env file
  const envContent = fs.readFileSync(envPath, 'utf8');
  const envVars = parseEnvFile(envContent);

  // Check required keys
  console.log('--- Required Credentials ---');
  let missingCount = 0;
  let canaryCount = 0;

  for (const key of EXPECTED_KEYS) {
    if (!envVars[key]) {
      console.log(`❌ ${key}: NOT SET`);
      missingCount++;
    } else {
      const value = envVars[key];
      if (isCanaryValue(value)) {
        console.log(`✓ ${key}: Set (CANARY value for testing)`);
        canaryCount++;
      } else {
        console.log(`⚠️  ${key}: Set (non-canary value - check if intentional)`);
      }
    }
  }

  // Check optional keys
  console.log('\n--- Optional Configuration ---');
  for (const key of OPTIONAL_KEYS) {
    if (envVars[key]) {
      const value = envVars[key];
      if (isCanaryValue(value)) {
        console.log(`✓ ${key}: Set (CANARY value)`);
      } else {
        console.log(`✓ ${key}: Set`);
      }
    } else {
      console.log(`ℹ️  ${key}: Not set (will use default)`);
    }
  }

  // Validate format
  console.log('\n--- Validation Checks ---');
  let validationErrors = 0;

  // Check for empty values
  for (const [key, value] of Object.entries(envVars)) {
    if (!value) {
      console.log(`⚠️  ${key}: Empty value detected`);
    }
  }

  // Check for potential security issues
  const suspiciousPatterns = [
    { pattern: /password=/gi, description: "Unencrypted password in config" },
    { pattern: /secret=/gi, description: "Secret in config" },
    { pattern: /---BEGIN/, description: "Possible private key in config" }
  ];

  for (const [key, value] of Object.entries(envVars)) {
    for (const { pattern, description } of suspiciousPatterns) {
      if (pattern.test(value)) {
        console.log(`⚠️  ${key}: May contain sensitive data (${description})`);
      }
    }
  }

  // Summary
  console.log('\n=== Summary ===');
  console.log(`Total env vars found: ${Object.keys(envVars).length}`);
  console.log(`Required keys present: ${EXPECTED_KEYS.length - missingCount}/${EXPECTED_KEYS.length}`);
  console.log(`Test canary values: ${canaryCount}`);
  console.log(`Missing required keys: ${missingCount}`);

  if (missingCount > 0) {
    console.log('\n⚠️  Please add the missing environment variables to .env.test');
    console.log('   Use CANARY values for testing purposes.');
  } else if (canaryCount === EXPECTED_KEYS.length) {
    console.log('\n✓ All required credentials are properly configured with CANARY values');
  } else {
    console.log('\n✓ All required credentials are present');
  }

  return {
    envFileExists: true,
    missingKeys: EXPECTED_KEYS.filter(key => !envVars[key]),
    totalKeysFound: Object.keys(envVars).length,
    isProperlyConfigured: missingCount === 0
  };
}

// Run verification
try {
  const result = verifyEnvConfig();
  process.exit(result.isProperlyConfigured ? 0 : 1);
} catch (error) {
  console.error('❌ Verification failed:', error.message);
  process.exit(1);
}

