app.use(express.urlencoded({
  extended: true,
  limit: '10kb',
  parameterLimit: 1000,
}));

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Validate input for user-related operations
const validateId = param('id')
  .isInt({ min: 1, max: 2147483647 })
  .withMessage('ID must be a positive integer');

const validateUserIdQuery = query('id')
  .optional()
  .isInt({ min: 1, max: 2147483647 })
  .withMessage('User ID must be a positive integer');

const validateUserCreate = [
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .matches(/^[a-zA-Z\s'-]+$/)
    .withMessage('Name can only contain letters, spaces, apostrophes, and hyphens'),

  body('email')
    .trim()
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail({
      remove_dots: false,
      remove_extension: false,
      gmail_remove_dots: false,
      gmail_remove_subaddress: false,
    }),

  body('role')
    .optional()
    .trim()
    .isIn(['user', 'admin', 'guest'])
    .withMessage('Role must be one of: user, admin, guest'),
];

// Validate patch/update inputs
const validateUserUpdate = [
  body('name')
    .optional()
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters'),

  body('email')
    .optional()
    .trim()
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail(),

  body('role')
    .optional()
    .trim()
    .isIn(['user', 'admin', 'guest'])
    .withMessage('Role must be one of: user, admin, guest'),
];

// Safe error handling middleware
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);

  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
        value: err.value,
      })),
    });
  }

  next();
};

// Error handling middleware - MUST be last
const errorHandler = (err, req, res, next) => {
  // Log error details for debugging (but don't expose to client)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV !== 'production' ? err.stack : undefined,
    type: err.constructor.name,
  });

  // Send generic error message to client
  res.status(err.status || 500).json({
    error: err.status === 429 ? err.message : 'Internal server error',
  });
};

// Users endpoint with validation - GET /users
app.get('/users', validateUserIdQuery, handleValidationErrors, (req, res, next) => {
  try {
    // Hardcoded user data (in real app, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter users if ID query parameter is provided
    if (req.query.id) {
      const filteredUsers = users.filter(user => user.id === parseInt(req.query.id));

      if (filteredUsers.length === 0) {
        return res.status(404).json({ error: 'User not found' });
      }

      return res.json(filteredUsers);
    }

    res.json(users);
  } catch (error) {
    next(error);
  }
});

// Create user endpoint with validation - POST /users
app.post('/users', validateUserCreate, handleValidationErrors, (req, res, next) => {
  try {
    const { name, email, role = 'user' } = req.body;

    // In a real application, you would:
    // 1. Check if user already exists
    // 2. Hash passwords before storing
    // 3. Insert into database with parameterized queries

    const newUser = {
      id: 3, // In real app, this would come from the database
