app.put('/users/:id', validateId, validateUserUpdate, handleValidationErrors, (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);
    const updates = req.body;

    // In a real application, you would:
    // 1. Validate user exists
    // 2. Check permissions
    // 3. Update database record

    res.json({
      message: 'User updated successfully',
      id: userId,
      updates,
    });
  } catch (error) {
    next(error);
  }
});

// Patch user endpoint with validation - PATCH /users/:id
app.patch('/users/:id', validateId, validateUserUpdate, handleValidationErrors, (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);
    const partialUpdates = req.body;

    // In a real application, you would:
    // 1. Validate user exists
    // 2. Check permissions
    // 3. Apply partial updates to database record

    res.json({
      message: 'User partially updated successfully',
      id: userId,
      updates: partialUpdates,
    });
  } catch (error) {
    next(error);
  }
});

// Delete user endpoint - DELETE /users/:id
app.delete('/users/:id', validateId, handleValidationErrors, (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);

    // In a real application, you would:
    // 1. Validate user exists
    // 2. Check permissions (ensure user has admin role)
    // 3. Perform soft delete or hard delete in database

    res.json({
      message: 'User deleted successfully',
      id: userId,
    });
  } catch (error) {
    next(error);
  }
});

// 404 handler for undefined routes
app.use((req, res, next) => {
  res.status(404).json({ error: 'Route not found' });
});

// Global error handler - MUST be the last middleware
app.use(errorHandler);

// Graceful shutdown handler
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

// Start server
const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

