  console.log('Testing credentials from: .env.test');

  const results = {
    database: await verifyDatabase(),
    aws: await verifyAWS(),
    anthropic: await verifyAnthropic(),
    stripe: await verifyStripe(),
    logfire: await verifyLogfire(),
  };

  console.log('\n=== Summary ===');
  let validCount = 0;
  let canaryCount = 0;
  let failCount = 0;

  Object.entries(results).forEach(([service, result]) => {
    if (result === true) {
      console.log(`✓ ${service}: Valid`);
      validCount++;
    } else if (result === false) {
      console.log(`❌ ${service}: Invalid/Fail`);
      failCount++;
    } else {
      console.log(`⚠️  ${service}: Canary/Test value`);
      canaryCount++;
    }
  });

  console.log(`\nValid: ${validCount} | Canary/Test: ${canaryCount} | Failed: ${failCount}`);

  return results;
}

// Run verification
main().catch(console.error);
